  border-radius: 20px;
  background: rgba(139, 92, 246, 0.0

前言jstack排查线程问题时，看到WAITING、BLOCKED、TIMED_WAITING一脸懵。2023年在实际项目系统学习线程生命周期后，看线程堆栈不再迷茫。线程状态转换是并发编程的基石，不理解状态转换，就无法理解锁、线程池、并发工具的底层行为，更无法在线上快速定位线程相关的问题。这篇文章从Thread.State枚举出发，结合实际项目大量实战案例，深入剖析Java线程六种状态的转换机制、触发条件、排查方法与工程最佳实践。

一、线程的六种状态1.1 Thread.State枚举定义Java线程的生命周期由java.lang.Thread.State枚举定义，共有六种状态：
// JDK源码：java.lang.Thread.Statepublic enum State &#123;    /**     * 线程对象已创建但尚未启动（未调用start()）     */    NEW,    /**     * 线程正在JVM中执行，等待操作系统调度     * 包含就绪（Ready）和运行中（Running）两种子状态     */    RUNNABLE,    /**     * 线程等待获取synchronized监视器锁     * 进入synchronized方法/代码块时，锁被其他线程持有     */    BLOCKED,    /**     * 线程无限期等待被其他线程显式唤醒     * 触发方式：Object.wait() / Thread.join() / LockSupport.park()     */    WAITING,    /**     * 线程在指定时间内等待被唤醒或超时自动返回     * 触发方式：Thread.sleep() / Object.wait(timeout) / Thread.join(timeout

前言 在实际场景中，生产环境监控大屏加载一条SQL耗时8秒，运营人员疯狂刷新页面导致数据库连接池耗尽。拿到慢查询日志后，面对EXPLAIN的12个字段一脸茫然——只知道type&#x3D;ALL要优化，但key_len是什么？filtered有什么用？Extra的Using index condition和Using where区别在哪？2023年花了整整两周深入理解EXPLAIN每个字段，从此SQL优化从”碰运气”变成”精准打击”。本文将结合实际项目的真实场景，系统讲解EXPLAIN执行计划的每个字段含义与实战分析技巧。 EXPLAIN基础概述什么是EXPLAINEXPLAIN是MySQL提供的SQL执行计划分析工具，它不会真正执行SQL，而是展示MySQL优化器选择的执行方案。通过EXPLAIN，我们可以了解SQL将如何访问表、使用哪些索引、扫描多少行数据、是否需要额外排序等关键信息。 -- 基本用法EXPLAIN SELECT * FROM t_device_alarm WHERE device_id = &#x27;D20230001&#x27; AND alarm_level &gt; 2;-- MySQL 8.0+ 更详细的格式EXPLAIN FORMAT=TREE SELECT * FROM t_device_alarm WHERE device_id = &#x27;D20230001&#x27; AND alarm_level &gt; 2;-- MySQL 8.0.16+ 分析格式（含成本估算）EXPLAIN ANALYZE SELECT * FROM t_device_alarm WHERE device_id = &#x27;D20230001&#x27; AND alarm_level &gt; 2;
输出字段全览
字段 说明 重要性 智慧矿

前言 线上一个订单列表接口从50ms飙升到2秒，排查发现是索引失效导致全表扫描。加了索引不等于一定走索引，很多写法会导致索引”隐形失效”。梳理所有索引失效场景，形成排查清单，从此慢查询优化有据可依。 场景一：索引列使用函数失效SQL-- 订单表有 create_time 索引SELECT * FROM `order` WHERE DATE(create_time) = &#x27;2023-06-01&#x27;;-- 索引失效！对索引列使用函数，优化器无法使用索引
优化方案-- 方案1：改写条件，避免对索引列使用函数SELECT * FROM `order` WHERE create_time &gt;= &#x27;2023-06-01&#x27; AND create_time &lt; &#x27;2023-06-02&#x27;;-- 方案2：使用函数索引（MySQL 8.0+）ALTER TABLE `order` ADD INDEX idx_create_time_date ((DATE(create_time)));
场景二：索引列参与计算失效SQL-- amount 字段有索引SELECT * FROM `order` WHERE amount / 2 = 100;-- 索引失效！索引列参与计算SELECT * FROM `order` WHERE amount + 10 &gt; 200;-- 索引失效！
优化方案-- 将计算移到等号右边SELECT * FROM `order` WHERE amount = 100 * 2;SELECT * FROM `order` WHERE amount &gt; 200 - 10;
场景三：隐式类型转换失效SQL-- order_no 是 VARCHAR 类型，有索引SELECT * FROM `or

前言 线上一次死锁事故：两个事务互相等待对方释放锁，导致业务超时。排查时发现对MySQL锁机制一知半解，不知道什么是间隙锁、什么时候会加表锁。2023年深入InnoDB锁机制后，终于能从锁的角度分析并发问题。 MySQL锁的分类按粒度分：├── 全局锁：FTWRL，备份时使用├── 表级锁│ ├── 表锁：LOCK TABLES│ ├── 元数据锁(MDL)：自动加，防DDL冲突│ └── 意向锁：IS/IX，表级标记└── 行级锁（InnoDB特有） ├── 记录锁(Record Lock)：锁单行 ├── 间隙锁(Gap Lock)：锁间隙，防幻读 └── 临键锁(Next-Key Lock)：记录锁+间隙锁
表级锁表锁-- 加读锁（其他线程可读不可写）LOCK TABLES user READ;SELECT * FROM user; -- ✅UPDATE user SET name=&#x27;李四&#x27; WHERE id=1; -- ❌UNLOCK TABLES;-- 加写锁（其他线程不可读不可写）LOCK TABLES user WRITE;
元数据锁（MDL）-- MySQL 5.5+自动加MDL，防止DDL与DML冲突-- 线程1：查询（自动加MDL读锁）SELECT * FROM user; -- 长时间运行-- 线程2：修改表结构（需要MDL写锁）ALTER TABLE user ADD COLUMN phone VARCHAR(20); -- 阻塞等待-- 线程3：查询（需要MDL读锁）SELECT * FROM user; -- 也被阻塞！-- 危险：线程1未提交 → 线程2等MDL写锁 → 线程3等MDL读锁 → 连锁阻塞-- 解决：设置DDL等待超时ALTER TABLE user ADD COLU

前言项目从单体拆分微服务后，服务间调用成了核心问题。最初用RestTemplate手动调用，代码又丑又难维护。2023年引入OpenFeign后，服务间调用像调用本地方法一样简单。在实际场景中，微服务架构下的服务调用更加复杂——设备服务、告警服务、人员服务、安全服务等之间频繁交互，任何调用失败都可能影响矿山安全。
一、微服务调用架构全貌架构流程： flowchart TD CLIENT["客户端请求"] GW["API Gateway・统一入口"] subgraph REGS["服务注册中心 Nacos/Consul"] REG["服务实例注册与发现"] end subgraph SVC["业务微服务"] DEV["设备服务"] ALARM["告警服务"] USER["人员服务"] end FEIGN["OpenFeign・声明式服务调用"] CLIENT --> GW GW --> SVC SVC --> REG FEIGN --> SVC
2.1 RestTemplate的问题@Servicepublic class OrderService &#123; @Autowired @LoadBalanced private RestTemplate restTemplate; public User getUser(Long userId) &#123; return restTemplate.getForObject( &quot;http://user-service/user/&quot; + userId, User.class); &#125;

前言多线程开发中，锁是最基本的同步工具。早期只知道synchronized，后来发现还有ReentrantLock、ReadWriteLock。到底该用哪个？它们的底层实现有什么区别？2023年系统学习后终于搞清楚了。在实际场景中，我们面临着设备数据并发采集、井下人员定位并发更新、传感器数据实时同步等大量并发场景，锁的选择直接影响系统的稳定性和性能。
一、并发锁全貌架构图架构流程： flowchart TD N1["Java 并发锁全景"] N2["SynchronizedJVM 内置锁"] N3["ReentrantLockJUC 显式锁"] N4["ReentrantReadWriteLock读写锁"] N5["StampedLock乐观读"] N6["AQSAbstractQueuedSynchronizer"] N7["偏向锁 → 轻量级锁 → 重量级锁"] N1 --> N2 N1 --> N3 N3 --> N4 N3 --> N5 N2 --> N7 N3 --> N6 N4 --> N6 N5 --> N6
二、Synchronized——JVM内置锁2.1 基本用法// 1. 修饰实例方法：锁当前对象public synchronized void method() &#123; // 同一实例的该方法同一时刻只能一个线程执行&#125;// 2. 修饰静态方法：锁Class对象public static synchronized void method() &#123; // 该类的所有实例同一时刻只能一个线程执行&#125;// 3. 修饰代码块：锁指定对象public void method() &#123;

前言在智慧矿山项目中，设备状态、告警级别、人员角色等场景经常需要使用固定的常量值。最初我用public static final定义常量，但遇到了类型安全问题——一个方法接受设备状态参数，却可以传入任意整数。后来改用枚举，不仅保证了类型安全，还能为每个枚举值添加自定义属性和方法，代码更加清晰和健壮。
传统常量方式 vs 枚举方式：
// ❌ 传统常量：类型不安全，传个 99 编译器也不拦public static final int NORMAL  = 1;public static final int WARNING = 2;public static final int ERROR   = 3;// ✅ 枚举：值域封闭，还能携带属性和方法public enum DeviceStatus &#123;    NORMAL(1), WARNING(2), ERROR(3);    private final int code;    DeviceStatus(int code) &#123; this.code = code; &#125;    public int getCode() &#123; return code; &#125;&#125;



一、什么是枚举？1.1 枚举的本质// 枚举定义public enum DeviceStatus &#123;    NORMAL,    // 正常    WARNING,   // 警告    ERROR      // 错误&#125;// 枚举编译后的等价形式（简化）public final class DeviceStatus extends Enum&lt;DeviceStatus&gt; &#123;    public static final DeviceStatus NORMAL = new Dev

前言NullPointerException是Java开发者最常遇到的异常，没有之一。在实际项目前半年，80%的运行时异常都是空指针——矿工查询为空、设备关联位置缺失、预警处理人未分配。直到学会Optional，配合合理的判空逻辑，空指针异常才真正从日常开发中消失。 场景1：矿工查询为null：
Miner miner &#x3D; service.getById(id); miner.getName() → NPE! 场景2：设备关联位置为null device.getLocation().getName() → NPE! 场景3：预警处理人为null alert.getHandler().getPhone() → NPE! 场景4：Map取值为null map.get(“key”).toString() → NPE! 场景5：自动拆箱为null int count &#x3D; getCount(); → NPE! 解决方案：Optional + 工具类判空 让”可能为空”在类型系统中显式表达
一、空指针的常见场景1.1 五大高发场景// 场景1：方法返回null，调用方没判空Miner miner = minerService.getById(id);String name = miner.getName(); // miner为null → NPE// 场景2：链式调用String city = device.getLocation().getName(); // location为null → NPE// 场景3：Map取值Object value = dictMap.get(&quot;key&quot;).toString(); // key不存在 → NPE// 场景4：自动拆箱int count = getActiveCount();

前言 开发完接口必须测试。最初我都是在浏览器手动输 URL——GET 还行，POST 带体、带头、带认证的接口根本没法测，只能临时写 main 方法调。后来系统学了 Postman，才发现它不只是”发请求的工具”：环境管理、脚本预处理、断言、集合运行器、Mock 服务，是一条完整的接口测试工作流。 这篇文章按”请求 → 环境 → 集合 → 自动化”四层展开，重点讲让效率翻倍的三个机制。 第一层：把请求发对GET 请求URL: &#123;&#123;base_url&#125;&#125;/api/usersParams: page: 1 size: 10 keyword: 张Headers: Authorization: Bearer &#123;&#123;token&#125;&#125;
Params 面板填的参数会自动拼到 URL 上，切换键值对形式比手拼 URL 字符串不易出错。 POST 请求（最常用的三种 Body）POST &#123;&#123;base_url&#125;&#125;/api/usersBody → raw → JSON（最常用，选 raw 后右侧类型切 JSON）:&#123; &quot;name&quot;: &quot;张三&quot;, &quot;age&quot;: 25, &quot;email&quot;: &quot;zhangsan@example.com&quot;, &quot;deptId&quot;: 1&#125;
Body 类型 适用场景 典型坑
raw + JSON REST 接口传 JSON 忘切 Content-Type，后端收不到字段
form-data 文件上传、混文件和字段 不能用 raw，要切 form-data
x-www-form

前言
实际场景中，定时任务无处不在：每天凌晨同步矿工考勤数据、每5分钟检查瓦斯超限报警、每小时统计各矿井产量、每10秒刷新井下人员定位缓存。最初我用Spring的@Scheduled注解，简单好用，但后来发现单线程执行定时任务有坑——瓦斯报警检查任务卡住，人员定位刷新任务就等着，这在矿山安全场景下是不可接受的。
@Scheduled基础开启定时任务@SpringBootApplication@EnableScheduling  // 开启定时任务public class MineApplication &#123;    public static void main(String[] args) &#123;        SpringApplication.run(MineApplication.class, args);    &#125;&#125;

固定速率// 每隔5秒执行一次（从上次开始时间算起）@Scheduled(fixedRate = 5000)public void fixedRateTask() &#123;    log.info(&quot;固定速率任务执行&quot;);&#125;// 每隔5秒执行一次（从上次结束时间算起）@Scheduled(fixedDelay = 5000)public void fixedDelayTask() &#123;    log.info(&quot;固定延迟任务执行&quot;);&#125;// 首次延迟10秒后执行@Scheduled(fixedRate = 5000, initialDelay = 10000)public void initialDelayTask() &#123;    log.info(&quot;首次延迟任务执行&quot;);&#125;

fixedRate vs fi

前言
在实际场景中，刚写Java的时候，@Override是我接触的第一个注解，当时只知道”加上它就表示重写父类方法”，至于注解是什么、怎么工作的、能不能自定义，完全没概念。直到用了Spring的@Component、@Autowired，我才开始好奇：这些注解到底是怎么起作用的？
注解是什么？注解（Annotation）是Java 5引入的一种元数据机制，为代码提供标记信息，本身不直接执行逻辑。
// 注解就像是给代码贴标签@Override       // 标记：这是重写方法@Deprecated     // 标记：这个方法已过时@SuppressWarnings(&quot;unchecked&quot;)  // 标记：忽略指定警告

关键认知：注解本身不做任何事，是”读”注解的代码在做事。
内置注解@Override// 编译期检查是否正确重写了父类方法@Overridepublic String toString() &#123;    return &quot;User&quot;;&#125;// 如果拼写错误，编译报错@Overrid  // 拼错public String tostring() &#123; &#125; // 编译报错：没有重写任何方法

@Deprecated// 标记已过时的方法，调用时编译器会警告@Deprecatedpublic void oldMethod() &#123;    // 旧逻辑，建议不再使用&#125;

@SuppressWarnings// 抑制编译器警告@SuppressWarnings(&quot;unchecked&quot;)  // 抑制泛型警告@SuppressWarnings(&quot;rawtypes&quot;)   // 抑制原始类型警告

元注解：定义注解的注解元注解用来修饰自定

前言 在实际场景中，重载（Overload）和重写（Override）是Java中最容易混淆的两个概念。刚入行的时候，我只知道”重载是方法名相同参数不同，重写是子类覆盖父类方法”，但真正在项目中遇到的问题远比这复杂：重载方法的匹配顺序是什么？重写时返回值可以不同吗？静态方法能被重写吗？ 重载（Overload）定义在同一个类中，方法名相同，参数列表不同（参数类型、个数、顺序不同），与返回值无关。 public class Calculator &#123; // 重载：方法名相同，参数不同 public int add(int a, int b) &#123; return a + b; &#125; public double add(double a, double b) &#123; return a + b; &#125; public int add(int a, int b, int c) &#123; return a + b + c; &#125;&#125;
重载的匹配规则当调用重载方法时，编译器按以下顺序匹配：
精确匹配 → 参数类型完全一致 基本类型自动转换 → int → long → float → double 自动装箱 → int → Integer 可变参数 → int… → 匹配
public void test(int i) &#123; System.out.println(&quot;int&quot;); &#125;public void test(long l) &#123; System.out.println(&quot;long&quot;); &#125;public void test(Integer i) &#123;

前言Spring事务是Java开发必须掌握的核心知识，但只背失效场景不够，面试官追问事务传播机制原理、AOP代理创建流程就会露馅。这篇文章从@Transactional源码到事务传播机制原理，从只读事务优化到多数据源事务，结合实际项目实战经验，全面深入分析Spring事务核心原理。

一、事务代理创建全流程1.1 @Transactional注解解析Spring容器启动时，@Transactional注解被SpringTransactionAnnotationParser解析为TransactionAttribute对象，最终注册到TransactionAttributeSource中。
// SpringTransactionAnnotationParser.javapublic class SpringTransactionAnnotationParser implements TransactionAnnotationParser &#123;    @Override    @Nullable    public TransactionAttribute parseTransactionAnnotation(AnnotatedElement element) &#123;        AnnotationAttributes attributes = AnnotatedElementUtils.findMergedAnnotationAttributes(                element, Transactional.class, false, false);        if (attributes != null) &#123;            return parseTransactionAnnotation(attributes);

前言在实际项目的电商模块建设中，我们面临了从零搭建订单系统的挑战。矿山物资采购场景下，订单链路涉及多种支付渠道、大额交易、复杂的售后退货流程，以及秒杀抢购时的高并发冲击。承接上篇内容，本文将继续深入讲解支付集成架构、支付回调处理、支付对账、订单超时取消、退款流程设计、订单查询优化、订单导出优化、订单统计设计、售后系统、订单状态通知、高并发订单设计等核心模块，并总结项目实战中遇到的常见问题与解决方案。

七、支付集成架构7.1 多渠道支付统一接入在实际场景中，我们需要同时对接支付宝、微信支付两大主流渠道，同时预留银联、企业对公转账等渠道的扩展能力。核心设计思路是采用策略模式 + 工厂模式实现支付渠道的统一抽象与灵活切换。
/** * 支付渠道策略接口 */public interface PaymentChannelStrategy &#123;    /**     * 获取渠道标识     */    String getChannelCode();    /**     * 创建支付请求     */    PaymentCreateResult createPayment(PaymentCreateRequest request);    /**     * 查询支付状态     */    PaymentQueryResult queryPayment(String outTradeNo);    /**     * 关闭支付交易     */    PaymentCloseResult closePayment(String outTradeNo);    /**     * 申请退款     */    RefundResult applyRefund(RefundRequest request);    /**     * 验证回调签名     */    b

前言在实际项目的持续迭代中，数据导出功能从最初简单的Excel导出，逐步演变为需要支持CSV、PDF等多种格式，并且还要支持加密、压缩、水印、分页、审计日志等附加功能。早期我们采用”每种组合写一个类”的方式，3种格式乘以3种功能就是9个类，4种格式乘以5种功能直接飙升到20个类——类爆炸问题触目惊心。更致命的是，每新增一种格式或功能，所有排列组合都需要新增类，代码维护成本指数级增长。 工厂模式解决了”创建什么”的问题——根据导出类型动态创建对应的导出器；装饰器模式解决了”功能组合”的问题——动态叠加加密、压缩、水印等功能，像套娃一样层层包装。两者配合，4种格式+5种功能只需9个类而非20个，新增格式只需一个实现类，新增功能只需一个装饰器。 本文将以实际项目的导出功能为实战场景，从问题出发，系统性地阐述工厂模式与装饰器模式的设计原理、源码实现、组合策略、踩坑记录与最佳实践。
导出功能的演进历程阶段一：单格式导出项目初期，只有设备台账导出为Excel的需求。代码简单粗暴——一个 ExcelExportUtil 工具类搞定一切： public class ExcelExportUtil &#123; public static byte[] exportDeviceLedger(List&lt;Device&gt; devices) &#123; // 直接写死Excel生成逻辑 Workbook workbook = new XSSFWorkbook(); Sheet sheet = workbook.createSheet(&quot;设备台账&quot;); // ... 200行硬编码 return toBytes(workbook); &#125;&#125;
